import CryptoKit
import Foundation

public enum ClipboardPrivacy {
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    public static func shouldCapture(types: [String]) -> Bool {
        !types.isEmpty && !types.contains(where: skippedTypes.contains)
    }
}

public enum ClipKind: String, Codable, Sendable {
    case text, url, image
}

public struct ClipItem: Codable, Equatable, Identifiable, Sendable {
    public let id: UUID
    public let kind: ClipKind
    public let text: String?
    public let image: String?
    public let fingerprint: String
    public var copiedAt: Date
    public var pinned: Bool

    public init(id: UUID = UUID(), kind: ClipKind, text: String?, image: String?, fingerprint: String, copiedAt: Date, pinned: Bool = false) {
        self.id = id
        self.kind = kind
        self.text = text
        self.image = image
        self.fingerprint = fingerprint
        self.copiedAt = copiedAt
        self.pinned = pinned
    }

    public var imageFiles: [String] {
        guard let image else { return [] }
        return [image, ClipItem.thumbnailName(for: image)]
    }

    public static func thumbnailName(for image: String) -> String {
        image.replacingOccurrences(of: ".png", with: "-thumb.png")
    }

    public static func kind(of string: String) -> ClipKind {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace),
              let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https",
              url.host?.isEmpty == false else { return .text }
        return .url
    }

    public static func fingerprint(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}

public struct ClipboardHistory: Codable, Equatable, Sendable {
    public static let capacity = 100
    public static let maxTextBytes = 1_000_000

    public private(set) var items: [ClipItem]

    public init(items: [ClipItem] = []) {
        self.items = items
    }

    public func contains(fingerprint: String) -> Bool {
        items.contains { $0.fingerprint == fingerprint }
    }

    @discardableResult
    public mutating func insert(_ item: ClipItem) -> [ClipItem] {
        if let index = items.firstIndex(where: { $0.fingerprint == item.fingerprint }) {
            var existing = items.remove(at: index)
            existing.copiedAt = item.copiedAt
            items.insert(existing, at: 0)
            return []
        }
        items.insert(item, at: 0)
        var evicted: [ClipItem] = []
        while items.count > Self.capacity, let last = items.lastIndex(where: { !$0.pinned }) {
            evicted.append(items.remove(at: last))
        }
        return evicted
    }

    public mutating func togglePin(_ id: UUID) {
        guard let index = items.firstIndex(where: { $0.id == id }) else { return }
        items[index].pinned.toggle()
    }

    @discardableResult
    public mutating func remove(_ id: UUID) -> ClipItem? {
        guard let index = items.firstIndex(where: { $0.id == id }) else { return nil }
        return items.remove(at: index)
    }

    @discardableResult
    public mutating func clearUnpinned() -> [ClipItem] {
        let removed = items.filter { !$0.pinned }
        items.removeAll { !$0.pinned }
        return removed
    }

    @discardableResult
    public mutating func expire(now: Date, maxAge: TimeInterval = 24 * 3600) -> [ClipItem] {
        let cutoff = now.addingTimeInterval(-maxAge)
        let removed = items.filter { !$0.pinned && $0.copiedAt < cutoff }
        guard !removed.isEmpty else { return [] }
        items.removeAll { !$0.pinned && $0.copiedAt < cutoff }
        return removed
    }

    public func visible(matching query: String) -> [ClipItem] {
        let needle = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let matched = needle.isEmpty ? items : items.filter { item in
            guard let text = item.text else { return false }
            return text.range(of: needle, options: [.caseInsensitive, .diacriticInsensitive]) != nil
        }
        return matched.filter(\.pinned) + matched.filter { !$0.pinned }
    }
}
